<?php
declare(strict_types=1);require dirname(__DIR__).'/app/config/config.php';require APP_ROOT.'/app/core/database.php';require APP_ROOT.'/app/modules/searches/searches.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Identifiant invalide.');}
try{$uid=local_user_id();$s=db()->prepare('SELECT d.* FROM application_documents d JOIN applications a ON a.id=d.application_id WHERE d.id=? AND a.user_id=?');$s->execute([$id,$uid]);$d=$s->fetch();if(!$d){http_response_code(404);exit('Document introuvable.');}$path=APP_ROOT.'/storage/application-documents/'.$d['stored_name'];if(!is_file($path)){http_response_code(404);exit('Fichier absent.');}header('Content-Type: '.$d['mime_type']);header('X-Content-Type-Options: nosniff');header('Content-Disposition: attachment; filename="document"; filename*=UTF-8\'\''.rawurlencode($d['original_name']));header('Content-Length: '.filesize($path));readfile($path);}catch(Throwable $e){http_response_code(500);exit('Impossible de télécharger le document.');}
